import json

import pytest

from shelf import books, cli, export, report


def setup_function():
    books.clear()


def test_find_is_case_insensitive():
    books.add("Dune", "Frank Herbert")
    assert books.find("dune") == [{"title": "Dune", "author": "Frank Herbert"}]


@pytest.mark.parametrize("title", ["", "   "])
def test_add_rejects_blank_title(title):
    with pytest.raises(ValueError):
        books.add(title, "Herbert")
    assert books.all_books() == []


def test_by_author_counts():
    books.add("Dune", "Frank Herbert")
    books.add("Dune Messiah", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 2, "Jane Austen": 1}


def test_as_json():
    books.add("Emma", "Jane Austen")
    assert json.loads(report.as_json()) == {"summary": "1 books", "by_author": {"Jane Austen": 1}}


def test_version(capsys):
    with pytest.raises(SystemExit) as e:
        cli.main(["--version"])
    assert e.value.code == 0
    assert capsys.readouterr().out.strip() == "shelf 0.1.0"


def test_export_csv():
    books.add("Dune", "Frank Herbert")
    books.add("Emma, Revisited", "Jane Austen")
    assert export.export_csv() == 'title,author\nDune,Frank Herbert\n"Emma, Revisited",Jane Austen\n'
EOF
